def solve(s: str) -> int:
    """Convert a Roman numeral string to its integer value.
    Handles standard symbols I, V, X, L, C, D, M and subtractive notation.
    """
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    i = 0
    while i < len(s):
        # If this and next form a subtractive pair, handle it.
        if i + 1 < len(s) and values[s[i]] < values[s[i + 1]]:
            total += values[s[i + 1]] - values[s[i]]
            i += 2
        else:
            total += values[s[i]]
            i += 1
    return total

